Content guardrails for the MLflow AI Gateway.

A guardrail wraps a scorer (an MLflow GenAI scorer or judge) and applies it to requests and/or
responses flowing through the gateway. Depending on its configured action, a guardrail either
validates the content (blocking it when the scorer fails) or sanitizes it (rewriting the content
through a configured LLM endpoint).
"""

from __future__ import annotations

import json
from typing import Any

from mlflow.entities.gateway_guardrail import GuardrailAction, GuardrailStage
from mlflow.gateway.providers.utils import send_request
from mlflow.types.chat import ChatCompletionRequest

_SANITIZATION_PATH = "gateway/mlflow/v1/chat/completions"


class GuardrailViolation(Exception):
    """
    Exception raised when a guardrail blocks a request or response.

    The error message includes the guardrail name and the scorer's rationale when available,
    otherwise it falls back to the generic message ``"blocked"``.
    """

    def __init__(self, name: str | None = None, rationale: str | None = None):
        self.name = name
        self.rationale = rationale or "blocked"
        if name:
            message = f"Guardrail '{name}' blocked the content: {self.rationale}"
        else:
            message = self.rationale
        super().__init__(message)


def _is_passing_value(value: Any) -> bool:
    """Interpret a scalar scorer value as passing (True) or failing (False)."""
    # NB: bool must be checked before any int handling since bool is a subclass of int.
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        return value.lower() == "yes"
    raise TypeError(f"unexpected value type for scorer result: {type(value).__name__}")


class JudgeGuardrail:
    """
    Guardrail that uses a scorer function to validate or sanitize requests and responses flowing
    through the MLflow AI Gateway.
    """

    def __init__(
        self,
        scorer: Any,
        stage: GuardrailStage,
        action: GuardrailAction,
        name: str,
        action_llm_url: str = None,
        action_endpoint_name: str = None,
    ):
        self.scorer = scorer
        self.stage = stage
        self.action = action
        self.name = name
        self.action_llm_url = action_llm_url
        self.action_endpoint_name = action_endpoint_name

    async def process_request(self, request: dict) -> dict:
        if self.stage != GuardrailStage.BEFORE:
            return request
        result = self.scorer(inputs=request)
        return await self._apply_action(request, result)

    async def process_response(self, request: dict, response: dict) -> dict:
        if self.stage != GuardrailStage.AFTER:
            return response
        result = self.scorer(outputs=response)
        return await self._apply_action(response, result)

    def _evaluate(self, result: Any) -> tuple[bool, str | None]:
        """Return ``(passing, rationale)`` for a scorer result.

        A list result is passing only when every item passes; the rationale of the first failing
        item is returned otherwise.
        """
        from mlflow.entities.assessment import Feedback

        if isinstance(result, list):
            for item in result:
                passing, rationale = self._evaluate(item)
                if not passing:
                    return False, rationale
            return True, None
        if isinstance(result, Feedback):
            return _is_passing_value(result.value), result.rationale
        return _is_passing_value(result), None

    async def _apply_action(self, payload: dict, result: Any) -> dict:
        passing, rationale = self._evaluate(result)
        if passing:
            return payload
        if self.action == GuardrailAction.VALIDATION:
            raise GuardrailViolation(self.name, rationale)
        return await self._sanitize(payload)

    async def _sanitize(self, payload: dict) -> dict:
        from fastapi import HTTPException

        if self.action_llm_url is None:
            raise GuardrailViolation(
                self.name,
                "action_llm_url is not configured for the sanitization endpoint",
            )

        sanitization_payload = {
            **payload,
            "model": self.action_endpoint_name,
            "response_format": {
                "type": "json_schema",
                "json_schema": {
                    "name": "sanitized_payload",
                    "strict": False,
                    "schema": ChatCompletionRequest.model_json_schema(),
                },
            },
        }

        try:
            response = await send_request(
                headers={},
                base_url=self.action_llm_url,
                path=_SANITIZATION_PATH,
                payload=sanitization_payload,
            )
        except HTTPException as e:
            raise GuardrailViolation(self.name, f"Sanitization request failed: {e.detail}")

        content = response["choices"][0]["message"]["content"]
        try:
            return json.loads(content)
        except (TypeError, ValueError):
            raise GuardrailViolation(self.name, "Sanitization response contained invalid JSON")

    @classmethod
    def from_entity(cls, entity: Any, server_url: str = None) -> "JudgeGuardrail":
        from mlflow.genai.judges.instructions_judge import InstructionsJudge
        from mlflow.genai.scorers import Scorer

        scorer = Scorer.model_validate(entity.scorer.serialized_scorer)

        if entity.action_endpoint_name is not None:
            action_endpoint_name = entity.action_endpoint_name
            action_llm_url = server_url
        else:
            action_endpoint_name = None
            action_llm_url = None

        if isinstance(scorer, InstructionsJudge) and scorer.model.startswith("gateway:/"):
            scorer._model = "openai:/" + scorer.model[len("gateway:/") :]
            scorer._base_url = f"{server_url}/gateway/mlflow/v1/chat/completions"

        return cls(
            scorer=scorer,
            stage=entity.stage,
            action=entity.action,
            name=entity.name,
            action_llm_url=action_llm_url,
            action_endpoint_name=action_endpoint_name,
        )
